import React, { useState, useEffect, useCallback } from "react";
import { useParams, useLocation, useNavigate } from "react-router-dom";
import BudgetCard from "../components/BudgetCard";
import AddExpenseForm from "../components/AddExpenseForm";
import ConfirmDeleteModal from "../components/ConfirmDeleteModal";
import { Trash2 } from "lucide-react";
import axios from "../utils/axios";
import toast from "react-hot-toast";

const Expenses = () => {
  const { budgetId } = useParams();
  const { state } = useLocation();
  const navigate = useNavigate();

  const [budget, setBudget] = useState(state?.budget || null);
  const [currentPage, setCurrentPage] = useState(1);
  const [showExpenseModal, setShowExpenseModal] = useState(false);
  const [showBudgetModal, setShowBudgetModal] = useState(false);
  const [expenseToDelete, setExpenseToDelete] = useState(null);
  const [selectedMonth, setSelectedMonth] = useState(
    state?.selectedMonth || new Date().getMonth() + 1
  );
  const [selectedYear, setSelectedYear] = useState(
    state?.selectedYear || new Date().getFullYear()
  );

  const itemsPerPage = 5;

  const fetchBudget = useCallback(async () => {
    if (!budgetId) return;
    try {
      const email = localStorage.getItem("email");
      const response = await axios.get(`/api/budgets/${budgetId}`, {
        headers: { email },
      });
      setBudget(response.data);
    } catch (err) {
      toast.error("Failed to fetch budget");
    }
  }, [budgetId]);

  useEffect(() => {
    fetchBudget();
  }, [fetchBudget]);

  const handleExpenseAdded = () => fetchBudget();

  const handleDeleteExpense = async () => {
    if (!expenseToDelete || !budgetId) return;
    try {
      const email = localStorage.getItem("email");
      await axios.delete(`/api/budgets/${budgetId}/expenses/${expenseToDelete}`, {
        headers: { email },
      });
      toast.success("Expense deleted!");
      setShowExpenseModal(false);
      setExpenseToDelete(null);
      fetchBudget();
    } catch (error) {
      toast.error("Failed to delete expense.");
    }
  };

  const handleDeleteBudget = async () => {
    try {
      const email = localStorage.getItem("email");
      await axios.delete(`/api/budgets/${budgetId}`, {
        headers: { email },
      });
      toast.success("Budget deleted!");
      navigate("/budgets");
    } catch (err) {
      toast.error("Failed to delete budget.");
    }
  };

  const isRecent = (date) => {
    const diff = Date.now() - new Date(date).getTime();
    return diff < 24 * 60 * 60 * 1000;
  };

  if (!budget) {
    return (
      <div className="ml-64 p-6">
        <p className="text-lg text-gray-700">Loading budget...</p>
      </div>
    );
  }

  const filteredExpenses = (budget.expenses || []).filter((expense) => {
    const date = new Date(expense.date);
    return (
      date.getMonth() + 1 === selectedMonth &&
      date.getFullYear() === selectedYear
    );
  });

  const totalPages = Math.ceil(filteredExpenses.length / itemsPerPage);
  const currentExpenses = filteredExpenses
    .slice()
    .sort((a, b) => new Date(b.date) - new Date(a.date))
    .slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  return (
    <div className="ml-64 p-6 flex flex-col gap-6">
      {/* Header */}
      <div className="flex justify-between items-center mb-4">
        <div className="flex gap-4 items-center">
          <select
            value={selectedMonth}
            onChange={(e) => { setSelectedMonth(Number(e.target.value)); setCurrentPage(1); }}
            className="border px-2 py-1 rounded"
          >
            {Array.from({ length: 12 }, (_, i) => (
              <option key={i + 1} value={i + 1}>
                {new Date(0, i).toLocaleString("default", { month: "long" })}
              </option>
            ))}
          </select>
          <select
            value={selectedYear}
            onChange={(e) => { setSelectedYear(Number(e.target.value)); setCurrentPage(1); }}
            className="border px-2 py-1 rounded"
          >
            {[2024, 2025, 2026].map((year) => (
              <option key={year} value={year}>{year}</option>
            ))}
          </select>
        </div>
        <button
          onClick={() => setShowBudgetModal(true)}
          className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700 transition"
        >
          🗑 Discard Budget
        </button>
      </div>

      {/* Budget Card + Add Expense Form */}
      <div className="w-full flex gap-6">
        <div className="w-1/2">
          <BudgetCard
            icon={budget.icon}
            name={budget.name}
            amount={budget.amount}
            spent={filteredExpenses.reduce((sum, e) => sum + (e.amount || 0), 0)}
            itemsCount={filteredExpenses.length}
          />
        </div>
        <div className="w-1/2">
          <AddExpenseForm budgetId={budgetId} onExpenseAdded={handleExpenseAdded} />
        </div>
      </div>

      {/* Expenses Table */}
      <div className="mt-4 bg-white rounded-xl shadow-md p-4">
        <h3 className="text-xl font-semibold mb-3">Latest Expenses</h3>
        <table className="w-full table-auto border-collapse">
          <thead>
            <tr className="bg-gray-100">
              <th className="p-2 text-left">Description</th>
              <th className="p-2 text-right">Amount (RM)</th>
              <th className="p-2 text-right">Date</th>
              <th className="p-2 text-center">Action</th>
            </tr>
          </thead>
          <tbody>
            {currentExpenses.map((expense) => (
              <tr
                key={expense.id}
                className={isRecent(expense.date) ? "bg-yellow-50" : "border-t"}
              >
                <td className="p-2">{expense.description}</td>
                <td className="p-2 text-right">RM {(expense.amount || 0).toFixed(2)}</td>
                <td className="p-2 text-right">
                  {new Date(expense.date).toLocaleDateString("ms-MY", {
                    year: "numeric",
                    month: "long",
                    day: "numeric",
                  })}
                </td>
                <td className="p-2 text-center">
                  <button
                    onClick={() => {
                      setExpenseToDelete(expense.id);
                      setShowExpenseModal(true);
                    }}
                    className="text-red-500 hover:text-red-700"
                  >
                    <Trash2 size={16} />
                  </button>
                </td>
              </tr>
            ))}
            {currentExpenses.length === 0 && (
              <tr>
                <td colSpan="4" className="text-center p-4 text-gray-500">
                  No expenses found for this period.
                </td>
              </tr>
            )}
          </tbody>
        </table>

        {totalPages > 1 && (
          <div className="flex justify-center mt-4 gap-2">
            <button
              disabled={currentPage === 1}
              onClick={() => setCurrentPage(currentPage - 1)}
              className="px-3 py-1 bg-gray-200 hover:bg-gray-300 rounded disabled:opacity-50"
            >
              Prev
            </button>
            <span className="px-3 py-1 text-gray-700">
              Page {currentPage} of {totalPages}
            </span>
            <button
              disabled={currentPage === totalPages}
              onClick={() => setCurrentPage(currentPage + 1)}
              className="px-3 py-1 bg-gray-200 hover:bg-gray-300 rounded disabled:opacity-50"
            >
              Next
            </button>
          </div>
        )}
      </div>

      <ConfirmDeleteModal
        isOpen={showExpenseModal}
        onClose={() => setShowExpenseModal(false)}
        onConfirm={handleDeleteExpense}
        message="Delete this expense?"
      />
      <ConfirmDeleteModal
        isOpen={showBudgetModal}
        onClose={() => setShowBudgetModal(false)}
        onConfirm={handleDeleteBudget}
        message="Delete this budget and ALL its expenses?"
      />
    </div>
  );
};

export default Expenses;
